// Pega o binário da imagem baixada e converte para Base64
const binaryData = await this.helpers.getBinaryDataBuffer(0, 'data');
const base64Clean = binaryData.toString('base64');

// Pega o prompt do Loop Over Items (usando first() para pegar o item)
const loopItem = $('Loop Over Items').first();
const promptRaw = loopItem.json.output || '';

const promptClean = String(promptRaw)
  .replace(/\n/g, ' ')
  .replace(/\r/g, ' ')
  .replace(/\t/g, ' ')
  .replace(/"/g, "'")
  .replace(/PROMPT FINAL 1/g, '')
  .trim();

return {
  imageBase64: base64Clean,
  prompt: promptClean
};

const parts = items[0].json.candidates[0].content.parts;

// Pega a parte que contém imagem
const imagePart = parts.find(p => p.inlineData && p.inlineData.mimeType.startsWith('image/'));

if (!imagePart) {
  throw new Error('Nenhuma imagem encontrada na resposta do Gemini');
}

const base64Image = imagePart.inlineData.data;
const mimeType = imagePart.inlineData.mimeType; // 'image/png'

return [{
  json: {
    success: true,
    mimeType: mimeType
  },
  binary: {
    data: {
      data: base64Image,
      mimeType: mimeType,
      fileName: 'imagem_gerada.png',
      fileExtension: 'png'
    }
  }
}];

